class Solution:
    def removeNthFromEnd(self, head: Optional[ListNode], n: int) -> Optional[ListNode]:
        length = 0
        node = head
        while node:
            length += 1
            node = node.next

        dummy = ListNode(0, head)
        left = dummy
        for _ in range(length - n):
            left = left.next
        left.next = left.next.next
        return dummy.next
